-- Phase 19: fiscal/operational documents and accounting exports.
-- This module stores declared fiscal data and provider results. It never infers tax rules.
alter table public.plans add column if not exists fiscal_module_enabled boolean not null default true;
alter table public.plans add column if not exists fiscal_auto_issue_enabled boolean not null default false;
alter table public.plans add column if not exists supplier_document_import_enabled boolean not null default true;
alter table public.plans add column if not exists accounting_export_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists fiscal_module_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists fiscal_auto_issue_enabled boolean not null default false;
alter table public.store_feature_flags add column if not exists supplier_document_import_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists accounting_export_enabled boolean not null default true;

create table public.fiscal_profiles(
 id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade,
 store_id uuid references public.establishments(id) on delete cascade, legal_name text, trade_name text, tax_id text,
 state_registration text, municipal_registration text, declared_tax_regime text, fiscal_address jsonb not null default '{}'::jsonb,
 municipality_code text, provider text not null default 'manual', environment text not null default 'test' check(environment in('test','production')),
 issue_mode text not null default 'manual' check(issue_mode in('manual','order_confirmed','payment_confirmed','completed')),
 provider_config jsonb not null default '{}'::jsonb, credentials_configured boolean not null default false,
 certificate_expires_at timestamptz, retention_days integer not null default 1825 check(retention_days between 30 and 36500),
 status text not null default 'incomplete' check(status in('incomplete','ready','disabled','error')),
 updated_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create unique index fiscal_profiles_scope_uq on public.fiscal_profiles(organization_id,coalesce(store_id,'00000000-0000-0000-0000-000000000000'::uuid));

create table public.fiscal_member_permissions(
 organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,
 can_view boolean not null default false,can_issue boolean not null default false,can_cancel boolean not null default false,
 can_import boolean not null default false,can_export boolean not null default false,can_configure boolean not null default false,
 updated_at timestamptz not null default now(),primary key(organization_id,user_id)
);

create table public.product_fiscal_profiles(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,
 store_id uuid not null references public.establishments(id) on delete cascade,product_id uuid not null references public.products(id) on delete cascade,
 variation_id uuid references public.product_variations(id) on delete cascade,ncm text,cfop text,cest text,cst text,csosn text,
 origin_code text,unit_code text,tax_metadata jsonb not null default '{}'::jsonb,inherit_from_product boolean not null default true,
 verified_at timestamptz,updated_by uuid references auth.users(id) on delete set null,updated_at timestamptz not null default now()
);
create unique index product_fiscal_profiles_scope_uq on public.product_fiscal_profiles(product_id,coalesce(variation_id,'00000000-0000-0000-0000-000000000000'::uuid));

create table public.fiscal_documents(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,
 store_id uuid not null references public.establishments(id) on delete cascade,direction text not null check(direction in('issued','received')),
 document_type text not null,order_id uuid references public.orders(id) on delete set null,purchase_order_id uuid references public.purchase_orders(id) on delete set null,
 customer_id uuid references public.customers(id) on delete set null,supplier_id uuid references public.suppliers(id) on delete set null,
 status text not null default 'draft' check(status in('draft','pending','processing','authorized','rejected','cancelled','contingency','error')),
 provider text not null default 'manual',environment text not null default 'test' check(environment in('test','production')),
 provider_document_id text,document_number text,series text,access_key text,issued_at timestamptz,cancelled_at timestamptz,
 total_cents bigint not null default 0 check(total_cents>=0),xml_storage_path text,pdf_storage_path text,original_storage_path text,
 payload_hash text,idempotency_key text not null,error_code text,error_message text,retry_count integer not null default 0,
 max_retries integer not null default 5,next_retry_at timestamptz,reprocessible boolean not null default true,
 parsed_metadata jsonb not null default '{}'::jsonb,divergence_warnings jsonb not null default '[]'::jsonb,
 created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique(organization_id,provider,idempotency_key)
);
create index fiscal_documents_scope_idx on public.fiscal_documents(organization_id,store_id,direction,status,created_at desc);
create index fiscal_documents_order_idx on public.fiscal_documents(order_id) where order_id is not null;
create index fiscal_documents_purchase_idx on public.fiscal_documents(purchase_order_id) where purchase_order_id is not null;

create table public.fiscal_document_events(
 id uuid primary key default gen_random_uuid(),document_id uuid not null references public.fiscal_documents(id) on delete cascade,
 event_type text not null,status text,provider_event_id text,payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now()
);
create table public.fiscal_jobs(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,
 store_id uuid not null references public.establishments(id) on delete cascade,document_id uuid not null references public.fiscal_documents(id) on delete cascade,
 job_type text not null check(job_type in('issue','cancel','status','download','reprocess')),status text not null default 'queued' check(status in('queued','processing','completed','failed','dead_letter')),
 idempotency_key text not null unique,attempts integer not null default 0,max_attempts integer not null default 5,next_attempt_at timestamptz not null default now(),
 last_error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table public.fiscal_webhook_events(
 id uuid primary key default gen_random_uuid(),provider text not null,provider_event_id text not null,payload_hash text not null,
 signature_valid boolean not null default false,processed_at timestamptz,error_message text,created_at timestamptz not null default now(),unique(provider,provider_event_id)
);
create table public.fiscal_action_previews(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,
 store_id uuid not null references public.establishments(id) on delete cascade,document_id uuid references public.fiscal_documents(id) on delete cascade,
 requested_by uuid not null references auth.users(id) on delete cascade,action_type text not null check(action_type in('issue','cancel','reprocess','link_finance')),
 payload jsonb not null default '{}'::jsonb,confirmation_phrase text,expires_at timestamptz not null default(now()+interval '10 minutes'),confirmed_at timestamptz,created_at timestamptz not null default now()
);
create table public.digital_documents(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,
 store_id uuid references public.establishments(id) on delete cascade,category text not null check(category in('fiscal','receipt','purchase','contract','operational','other')),
 title text not null,description text,storage_path text not null,file_name text not null,mime_type text,size_bytes bigint check(size_bytes between 1 and 20971520),
 tags text[] not null default '{}',document_date date,retention_until date,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),unique(organization_id,storage_path)
);
create index digital_documents_search_idx on public.digital_documents using gin((to_tsvector('portuguese',coalesce(title,'')||' '||coalesce(description,''))));
create index digital_documents_tags_idx on public.digital_documents using gin(tags);
create table public.fiscal_magic_links(
 id uuid primary key default gen_random_uuid(),document_id uuid not null references public.fiscal_documents(id) on delete cascade,
 token_hash text not null unique,expires_at timestamptz not null,access_count integer not null default 0,max_access_count integer not null default 10,
 revoked_at timestamptz,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now()
);
create table public.accounting_export_batches(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,
 store_id uuid references public.establishments(id) on delete cascade,period_start date not null,period_end date not null,
 format text not null check(format in('csv','xlsx','xml','pdf','zip')),status text not null default 'pending' check(status in('pending','processing','ready','failed')),
 storage_path text,manifest jsonb not null default '{}'::jsonb,idempotency_key text not null,error_message text,created_by uuid references auth.users(id) on delete set null,
 created_at timestamptz not null default now(),completed_at timestamptz,unique(organization_id,idempotency_key),check(period_end>=period_start)
);
create table public.fiscal_provider_health(
 organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,
 provider text not null,status text not null default 'unknown' check(status in('unknown','healthy','degraded','offline','incomplete')),
 latency_ms integer,last_checked_at timestamptz,last_error text,primary key(organization_id,store_id,provider)
);

create or replace function private.fiscal_can_access(target_org uuid,target_store uuid,requested_permission text default 'view') returns boolean language sql stable security definer set search_path=public,private,pg_temp as $$
 select auth.uid() is not null and (
  exists(select 1 from public.organization_members om where om.organization_id=target_org and om.user_id=auth.uid() and om.active and om.role in('owner','admin','manager','supervisor') and (target_store is null or om.all_stores or exists(select 1 from public.organization_member_store_access a where a.organization_id=target_org and a.user_id=om.user_id and a.establishment_id=target_store)))
  or exists(select 1 from public.establishment_members em join public.establishments e on e.id=em.establishment_id where e.organization_id=target_org and em.user_id=auth.uid() and em.status='active' and em.role::text in('owner','manager') and (target_store is null or target_store=em.establishment_id))
  or exists(select 1 from public.fiscal_member_permissions p where p.organization_id=target_org and p.user_id=auth.uid() and case requested_permission when 'view' then p.can_view when 'issue' then p.can_issue when 'cancel' then p.can_cancel when 'import' then p.can_import when 'export' then p.can_export when 'configure' then p.can_configure else false end)
 )
$$;
revoke all on function private.fiscal_can_access(uuid,uuid,text) from public,anon;grant execute on function private.fiscal_can_access(uuid,uuid,text) to authenticated;

create or replace function private.fiscal_audit(target_org uuid,target_store uuid,target_action text,target_type text,target_id uuid,target_metadata jsonb default '{}'::jsonb) returns void language plpgsql security definer set search_path=public,pg_temp as $$
begin insert into public.audit_logs(establishment_id,actor_id,action,entity_type,entity_id,metadata) values(target_store,auth.uid(),target_action,target_type,target_id,target_metadata);end$$;
revoke all on function private.fiscal_audit(uuid,uuid,text,text,uuid,jsonb) from public,anon,authenticated;

alter table public.fiscal_profiles enable row level security;alter table public.fiscal_member_permissions enable row level security;alter table public.product_fiscal_profiles enable row level security;
alter table public.fiscal_documents enable row level security;alter table public.fiscal_document_events enable row level security;alter table public.fiscal_jobs enable row level security;
alter table public.fiscal_webhook_events enable row level security;alter table public.fiscal_action_previews enable row level security;alter table public.digital_documents enable row level security;
alter table public.fiscal_magic_links enable row level security;alter table public.accounting_export_batches enable row level security;alter table public.fiscal_provider_health enable row level security;
create policy fiscal_profiles_read on public.fiscal_profiles for select to authenticated using(private.fiscal_can_access(organization_id,store_id,'view'));
create policy fiscal_permissions_read on public.fiscal_member_permissions for select to authenticated using(private.fiscal_can_access(organization_id,null,'configure'));
create policy fiscal_product_profiles_read on public.product_fiscal_profiles for select to authenticated using(private.fiscal_can_access(organization_id,store_id,'view'));
create policy fiscal_documents_read on public.fiscal_documents for select to authenticated using(private.fiscal_can_access(organization_id,store_id,'view'));
create policy fiscal_events_read on public.fiscal_document_events for select to authenticated using(exists(select 1 from public.fiscal_documents d where d.id=document_id and private.fiscal_can_access(d.organization_id,d.store_id,'view')));
create policy fiscal_jobs_read on public.fiscal_jobs for select to authenticated using(private.fiscal_can_access(organization_id,store_id,'view'));
create policy fiscal_previews_read on public.fiscal_action_previews for select to authenticated using(requested_by=auth.uid() and private.fiscal_can_access(organization_id,store_id,'view'));
create policy digital_documents_read on public.digital_documents for select to authenticated using(private.fiscal_can_access(organization_id,store_id,'view'));
create policy accounting_exports_read on public.accounting_export_batches for select to authenticated using(private.fiscal_can_access(organization_id,store_id,'export'));
create policy fiscal_health_read on public.fiscal_provider_health for select to authenticated using(private.fiscal_can_access(organization_id,store_id,'view'));
grant select on public.fiscal_profiles,public.fiscal_member_permissions,public.product_fiscal_profiles,public.fiscal_documents,public.fiscal_document_events,public.fiscal_jobs,public.fiscal_action_previews,public.digital_documents,public.accounting_export_batches,public.fiscal_provider_health to authenticated;
revoke insert,update,delete on public.fiscal_profiles,public.fiscal_member_permissions,public.product_fiscal_profiles,public.fiscal_documents,public.fiscal_document_events,public.fiscal_jobs,public.fiscal_action_previews,public.digital_documents,public.accounting_export_batches,public.fiscal_provider_health from anon,authenticated;
revoke all on public.fiscal_webhook_events,public.fiscal_magic_links from anon,authenticated;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('fiscal-documents','fiscal-documents',false,20971520,array['application/pdf','application/xml','text/xml','text/csv','application/zip','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy fiscal_storage_read on storage.objects for select to authenticated using(bucket_id='fiscal-documents' and private.fiscal_can_access((storage.foldername(name))[1]::uuid,null,'view'));
create policy fiscal_storage_insert on storage.objects for insert to authenticated with check(bucket_id='fiscal-documents' and private.fiscal_can_access((storage.foldername(name))[1]::uuid,(storage.foldername(name))[2]::uuid,'import'));

create or replace function public.fiscal_configure_profile(requested_establishment_id uuid,requested_profile jsonb) returns public.fiscal_profiles language plpgsql security definer set search_path=public,private,pg_temp as $$declare org uuid;p public.fiscal_profiles;begin select organization_id into org from public.establishments where id=requested_establishment_id;if not private.fiscal_can_access(org,requested_establishment_id,'configure') then raise exception 'Sem permissão para configurar o fiscal';end if;if coalesce(requested_profile->>'provider','manual') not in('manual','sandbox_adapter') then raise exception 'Provedor fiscal ainda não implementado';end if;insert into public.fiscal_profiles(organization_id,store_id,legal_name,trade_name,tax_id,state_registration,municipal_registration,declared_tax_regime,fiscal_address,municipality_code,provider,environment,issue_mode,provider_config,status,updated_by) values(org,requested_establishment_id,nullif(btrim(requested_profile->>'legal_name'),''),nullif(btrim(requested_profile->>'trade_name'),''),nullif(btrim(requested_profile->>'tax_id'),''),nullif(btrim(requested_profile->>'state_registration'),''),nullif(btrim(requested_profile->>'municipal_registration'),''),nullif(btrim(requested_profile->>'declared_tax_regime'),''),coalesce(requested_profile->'fiscal_address','{}'::jsonb),nullif(btrim(requested_profile->>'municipality_code'),''),coalesce(requested_profile->>'provider','manual'),coalesce(requested_profile->>'environment','test'),coalesce(requested_profile->>'issue_mode','manual'),coalesce(requested_profile->'provider_config','{}'::jsonb),'incomplete',auth.uid()) on conflict(organization_id,coalesce(store_id,'00000000-0000-0000-0000-000000000000'::uuid)) do update set legal_name=excluded.legal_name,trade_name=excluded.trade_name,tax_id=excluded.tax_id,state_registration=excluded.state_registration,municipal_registration=excluded.municipal_registration,declared_tax_regime=excluded.declared_tax_regime,fiscal_address=excluded.fiscal_address,municipality_code=excluded.municipality_code,provider=excluded.provider,environment=excluded.environment,issue_mode=excluded.issue_mode,provider_config=excluded.provider_config,updated_by=auth.uid(),updated_at=now() returning * into p;perform private.fiscal_audit(org,requested_establishment_id,'fiscal_profile_updated','fiscal_profile',p.id,jsonb_build_object('provider',p.provider,'environment',p.environment,'status',p.status));return p;end$$;

create or replace function public.fiscal_save_product_profile(requested_establishment_id uuid,requested_product_id uuid,requested_variation_id uuid,requested_data jsonb) returns public.product_fiscal_profiles language plpgsql security definer set search_path=public,private,pg_temp as $$declare org uuid;r public.product_fiscal_profiles;begin select organization_id into org from public.establishments where id=requested_establishment_id;if not private.fiscal_can_access(org,requested_establishment_id,'configure') then raise exception 'Sem permissão';end if;if not exists(select 1 from public.products where id=requested_product_id and establishment_id=requested_establishment_id) then raise exception 'Produto inválido';end if;insert into public.product_fiscal_profiles(organization_id,store_id,product_id,variation_id,ncm,cfop,cest,cst,csosn,origin_code,unit_code,tax_metadata,inherit_from_product,verified_at,updated_by) values(org,requested_establishment_id,requested_product_id,requested_variation_id,nullif(requested_data->>'ncm',''),nullif(requested_data->>'cfop',''),nullif(requested_data->>'cest',''),nullif(requested_data->>'cst',''),nullif(requested_data->>'csosn',''),nullif(requested_data->>'origin_code',''),nullif(requested_data->>'unit_code',''),coalesce(requested_data->'tax_metadata','{}'::jsonb),coalesce((requested_data->>'inherit_from_product')::boolean,true),case when (requested_data->>'verified')::boolean then now() else null end,auth.uid()) on conflict(product_id,coalesce(variation_id,'00000000-0000-0000-0000-000000000000'::uuid)) do update set ncm=excluded.ncm,cfop=excluded.cfop,cest=excluded.cest,cst=excluded.cst,csosn=excluded.csosn,origin_code=excluded.origin_code,unit_code=excluded.unit_code,tax_metadata=excluded.tax_metadata,inherit_from_product=excluded.inherit_from_product,verified_at=excluded.verified_at,updated_by=auth.uid(),updated_at=now() returning * into r;perform private.fiscal_audit(org,requested_establishment_id,'product_fiscal_profile_updated','product_fiscal_profile',r.id,jsonb_build_object('product_id',requested_product_id));return r;end$$;

create or replace function public.fiscal_preview_action(requested_establishment_id uuid,requested_action text,requested_document_id uuid default null,requested_payload jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$declare org uuid;pid uuid;phrase text;perm text;begin select organization_id into org from public.establishments where id=requested_establishment_id;perm:=case requested_action when 'issue' then 'issue' when 'cancel' then 'cancel' when 'reprocess' then 'issue' when 'link_finance' then 'import' else 'none' end;if not private.fiscal_can_access(org,requested_establishment_id,perm) then raise exception 'Sem permissão para esta ação fiscal';end if;if requested_action='cancel' then phrase:='CANCELAR DOCUMENTO';end if;insert into public.fiscal_action_previews(organization_id,store_id,document_id,requested_by,action_type,payload,confirmation_phrase) values(org,requested_establishment_id,requested_document_id,auth.uid(),requested_action,requested_payload,phrase) returning id into pid;return jsonb_build_object('preview_id',pid,'action',requested_action,'document_id',requested_document_id,'requires_confirmation',true,'confirmation_phrase',phrase,'expires_at',now()+interval '10 minutes','warning',case when requested_action='cancel' then 'Cancelamento fiscal é irreversível no MasterApp e dependerá da autorização do provedor.' else 'Confira todos os dados declarados antes de continuar.' end);end$$;

create or replace function public.fiscal_confirm_action(requested_preview_id uuid,requested_confirmation_text text default null) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$declare p public.fiscal_action_previews;d public.fiscal_documents;jid uuid;begin select * into p from public.fiscal_action_previews where id=requested_preview_id and requested_by=auth.uid() for update;if p.id is null or p.confirmed_at is not null or p.expires_at<=now() then raise exception 'Prévia inválida ou expirada';end if;if p.confirmation_phrase is not null and requested_confirmation_text<>p.confirmation_phrase then raise exception 'Digite a frase de confirmação exatamente';end if;if p.action_type='issue' then insert into public.fiscal_documents(organization_id,store_id,direction,document_type,order_id,status,provider,environment,total_cents,payload_hash,idempotency_key,created_by) select p.organization_id,p.store_id,'issued',coalesce(p.payload->>'document_type','operational_receipt'),(p.payload->>'order_id')::uuid,'pending',coalesce(fp.provider,'manual'),coalesce(fp.environment,'test'),coalesce((p.payload->>'total_cents')::bigint,o.total_cents,0),encode(digest(p.payload::text,'sha256'),'hex'),coalesce(p.payload->>'idempotency_key',p.id::text),auth.uid() from public.orders o left join public.fiscal_profiles fp on fp.organization_id=p.organization_id and fp.store_id=p.store_id where o.id=(p.payload->>'order_id')::uuid and o.establishment_id=p.store_id returning * into d;if d.id is null then raise exception 'Pedido não encontrado na unidade';end if;insert into public.fiscal_jobs(organization_id,store_id,document_id,job_type,idempotency_key) values(p.organization_id,p.store_id,d.id,'issue','issue:'||d.id) returning id into jid;elsif p.action_type in('cancel','reprocess') then select * into d from public.fiscal_documents where id=p.document_id and organization_id=p.organization_id and store_id=p.store_id for update;if d.id is null then raise exception 'Documento não encontrado';end if;if p.action_type='cancel' and d.status<>'authorized' then raise exception 'Somente documento autorizado pode ser cancelado';end if;insert into public.fiscal_jobs(organization_id,store_id,document_id,job_type,idempotency_key) values(p.organization_id,p.store_id,d.id,p.action_type,p.action_type||':'||d.id||':'||p.id) returning id into jid;update public.fiscal_documents set status=case when p.action_type='cancel' then 'processing' else 'pending' end,retry_count=case when p.action_type='reprocess' then retry_count+1 else retry_count end,updated_at=now() where id=d.id returning * into d;else raise exception 'Ação não confirmada neste fluxo';end if;update public.fiscal_action_previews set confirmed_at=now() where id=p.id;perform private.fiscal_audit(p.organization_id,p.store_id,'fiscal_'||p.action_type||'_confirmed','fiscal_document',d.id,jsonb_build_object('job_id',jid));return jsonb_build_object('document_id',d.id,'job_id',jid,'status',d.status);end$$;

create or replace function public.fiscal_register_received_document(requested_establishment_id uuid,requested_storage_path text,requested_file_name text,requested_mime text,requested_supplier_id uuid default null,requested_purchase_order_id uuid default null,requested_metadata jsonb default '{}'::jsonb,requested_idempotency_key text default null) returns public.fiscal_documents language plpgsql security definer set search_path=public,private,pg_temp as $$declare org uuid;d public.fiscal_documents;warnings jsonb:='[]'::jsonb;begin select organization_id into org from public.establishments where id=requested_establishment_id;if not private.fiscal_can_access(org,requested_establishment_id,'import') then raise exception 'Sem permissão para importar documentos';end if;if requested_purchase_order_id is not null and not exists(select 1 from public.purchase_orders where id=requested_purchase_order_id and organization_id=org and establishment_id=requested_establishment_id) then raise exception 'Compra inválida';end if;if requested_purchase_order_id is not null and coalesce((requested_metadata->>'total_cents')::bigint,0)<>(select total_cents from public.purchase_orders where id=requested_purchase_order_id) then warnings:=jsonb_build_array('Valor do documento diverge do pedido de compra. Revise antes de receber o estoque.');end if;insert into public.fiscal_documents(organization_id,store_id,direction,document_type,purchase_order_id,supplier_id,status,provider,environment,total_cents,original_storage_path,payload_hash,idempotency_key,parsed_metadata,divergence_warnings,created_by) values(org,requested_establishment_id,'received',coalesce(requested_metadata->>'document_type','supplier_invoice'),requested_purchase_order_id,requested_supplier_id,'authorized','import','production',coalesce((requested_metadata->>'total_cents')::bigint,0),requested_storage_path,encode(digest(requested_metadata::text,'sha256'),'hex'),coalesce(requested_idempotency_key,encode(digest(requested_storage_path,'sha256'),'hex')),requested_metadata,warnings,auth.uid()) returning * into d;insert into public.digital_documents(organization_id,store_id,category,title,storage_path,file_name,mime_type,size_bytes,tags,document_date,created_by) values(org,requested_establishment_id,'purchase',requested_file_name,requested_storage_path,requested_file_name,requested_mime,coalesce((requested_metadata->>'size_bytes')::bigint,1),array['fornecedor','fiscal'],coalesce((requested_metadata->>'document_date')::date,current_date),auth.uid()) on conflict(organization_id,storage_path) do nothing;perform private.fiscal_audit(org,requested_establishment_id,'received_document_imported','fiscal_document',d.id,jsonb_build_object('purchase_order_id',requested_purchase_order_id,'warnings',warnings,'stock_changed',false));return d;end$$;

create or replace function public.fiscal_link_received_to_finance(requested_document_id uuid,requested_due_date date) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$declare d public.fiscal_documents;entry uuid;begin select * into d from public.fiscal_documents where id=requested_document_id and direction='received';if d.id is null or not private.fiscal_can_access(d.organization_id,d.store_id,'import') then raise exception 'Documento não encontrado';end if;insert into public.financial_entries(organization_id,store_id,type,source_type,source_id,description,amount_cents,due_date,status,created_by_user_id,idempotency_key,metadata) values(d.organization_id,d.store_id,'expense','fiscal_received_document',d.id,'Documento fiscal recebido '||coalesce(d.document_number,d.id::text),d.total_cents,requested_due_date,'pending',auth.uid(),'fiscal:'||d.id,jsonb_build_object('fiscal_document_id',d.id,'supplier_id',d.supplier_id)) on conflict(organization_id,source_type,source_id,type) do update set updated_at=financial_entries.updated_at returning id into entry;perform private.fiscal_audit(d.organization_id,d.store_id,'fiscal_document_linked_finance','financial_entry',entry,jsonb_build_object('document_id',d.id));return jsonb_build_object('financial_entry_id',entry,'duplicated',false);end$$;

create or replace function public.fiscal_phase19_summary(requested_establishment_id uuid,requested_start date default(current_date-30),requested_end date default current_date) returns jsonb language plpgsql stable security definer set search_path=public,private,pg_temp as $$declare org uuid;result jsonb;begin select organization_id into org from public.establishments where id=requested_establishment_id;if not private.fiscal_can_access(org,requested_establishment_id,'view') then raise exception 'Sem acesso ao módulo fiscal';end if;select jsonb_build_object('cards',jsonb_build_object('issued',(select count(*) from public.fiscal_documents where store_id=requested_establishment_id and direction='issued' and created_at::date between requested_start and requested_end),'authorized',(select count(*) from public.fiscal_documents where store_id=requested_establishment_id and status='authorized' and created_at::date between requested_start and requested_end),'received',(select count(*) from public.fiscal_documents where store_id=requested_establishment_id and direction='received' and created_at::date between requested_start and requested_end),'errors',(select count(*) from public.fiscal_documents where store_id=requested_establishment_id and status in('rejected','error') and created_at::date between requested_start and requested_end),'pending_jobs',(select count(*) from public.fiscal_jobs where store_id=requested_establishment_id and status in('queued','processing'))),'profile',(select to_jsonb(p)-'tax_id' from public.fiscal_profiles p where p.organization_id=org and p.store_id=requested_establishment_id),'documents',(select coalesce(jsonb_agg(to_jsonb(d) order by d.created_at desc),'[]'::jsonb) from(select id,direction,document_type,order_id,purchase_order_id,supplier_id,status,provider,environment,document_number,series,total_cents,error_code,error_message,retry_count,reprocessible,divergence_warnings,issued_at,cancelled_at,created_at from public.fiscal_documents where store_id=requested_establishment_id and created_at::date between requested_start and requested_end limit 100)d),'exports',(select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) from(select id,period_start,period_end,format,status,storage_path,error_message,created_at,completed_at from public.accounting_export_batches where organization_id=org and (store_id is null or store_id=requested_establishment_id) limit 30)x),'health',(select coalesce(jsonb_agg(to_jsonb(h)),'[]'::jsonb) from public.fiscal_provider_health h where h.organization_id=org and h.store_id=requested_establishment_id),'security',jsonb_build_object('private_storage',true,'signed_urls_only',true,'tax_engine',false,'stock_auto_receipt',false)) into result;return result;end$$;

create or replace function public.fiscal_create_export(requested_establishment_id uuid,requested_start date,requested_end date,requested_format text,requested_idempotency_key text) returns public.accounting_export_batches language plpgsql security definer set search_path=public,private,pg_temp as $$declare org uuid;r public.accounting_export_batches;begin select organization_id into org from public.establishments where id=requested_establishment_id;if not private.fiscal_can_access(org,requested_establishment_id,'export') then raise exception 'Sem permissão para exportar';end if;if requested_format not in('csv','xlsx','xml','pdf','zip') then raise exception 'Formato inválido';end if;insert into public.accounting_export_batches(organization_id,store_id,period_start,period_end,format,status,manifest,idempotency_key,created_by) values(org,requested_establishment_id,requested_start,requested_end,requested_format,'pending',jsonb_build_object('scope','fiscal_and_financial','compatibility','generic'),requested_idempotency_key,auth.uid()) on conflict(organization_id,idempotency_key) do update set idempotency_key=excluded.idempotency_key returning * into r;perform private.fiscal_audit(org,requested_establishment_id,'accounting_export_requested','accounting_export',r.id,jsonb_build_object('format',requested_format,'period_start',requested_start,'period_end',requested_end));return r;end$$;

create or replace function public.fiscal_record_webhook(requested_provider text,requested_event_id text,requested_payload_hash text,requested_signature_valid boolean,requested_document_id uuid default null,requested_status text default null) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$declare event_id uuid;begin if auth.role()<>'service_role' then raise exception 'Somente serviço interno';end if;insert into public.fiscal_webhook_events(provider,provider_event_id,payload_hash,signature_valid,processed_at,error_message) values(requested_provider,requested_event_id,requested_payload_hash,requested_signature_valid,case when requested_signature_valid then now() else null end,case when requested_signature_valid then null else 'Assinatura inválida' end) on conflict(provider,provider_event_id) do update set provider_event_id=excluded.provider_event_id returning id into event_id;if requested_signature_valid and requested_document_id is not null and requested_status in('pending','processing','authorized','rejected','cancelled','contingency','error') then update public.fiscal_documents set status=requested_status,updated_at=now(),issued_at=case when requested_status='authorized' then coalesce(issued_at,now()) else issued_at end,cancelled_at=case when requested_status='cancelled' then now() else cancelled_at end where id=requested_document_id and provider=requested_provider;insert into public.fiscal_document_events(document_id,event_type,status,provider_event_id) values(requested_document_id,'provider_webhook',requested_status,requested_event_id);end if;return jsonb_build_object('event_id',event_id,'accepted',requested_signature_valid);end$$;

do $$declare f regprocedure;begin for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'fiscal_%' loop execute format('revoke all on function %s from public,anon',f);end loop;end$$;
grant execute on function public.fiscal_configure_profile(uuid,jsonb),public.fiscal_save_product_profile(uuid,uuid,uuid,jsonb),public.fiscal_preview_action(uuid,text,uuid,jsonb),public.fiscal_confirm_action(uuid,text),public.fiscal_register_received_document(uuid,text,text,text,uuid,uuid,jsonb,text),public.fiscal_link_received_to_finance(uuid,date),public.fiscal_phase19_summary(uuid,date,date),public.fiscal_create_export(uuid,date,date,text,text) to authenticated;
revoke all on function public.fiscal_record_webhook(text,text,text,boolean,uuid,text) from public,anon,authenticated;grant execute on function public.fiscal_record_webhook(text,text,text,boolean,uuid,text) to service_role;
